# 014 · CHECKLIST · personalidad antisocial
S("checklist", "RM-PSI-014", "Búsqueda del propio beneficio sin culpa ni cambio tras el daño ajeno: trastorno de personalidad antisocial",
  "Psiquiatría · personalidad antisocial",
  ("Personalidad antisocial", ["Grupo B (dramático, emocional, impulsivo): desprecio y violación de los derechos de los demás desde la infancia o adolescencia.", "Exige 18 años o más."]),
  ("Varón de 40 años", ["Prima su propia satisfacción a costa del sufrimiento ajeno.", "No cambia ni siente culpa a pesar de las consecuencias."]),
  ["DSM-5-TR: edad mínima de 18 años, trastorno de conducta antes de los 15 y tres o más criterios (normas legales, engaño, impulsividad, agresión, imprudencia, irresponsabilidad, falta de remordimiento).",
   "El dato que decide el caso es la ausencia de remordimiento y de culpa; el esquizoide es frío pero sin intención de dañar.",
   "Obsesivo: perfeccionismo y rigidez. Limítrofe: inestabilidad afectiva, miedo al abandono y autolesiones. Paranoide: desconfianza sistemática.",
   "No hay fármaco específico: psicoterapia de eficacia limitada y tratamiento de comorbilidades (consumo de sustancias). Se revisa la conducta antes de los 15 años."],
  DSM + "; " + KS + "; " + HARR + ".",
  op=("¿Trastorno de personalidad?", ["No: perfeccionismo y rigidez, con culpa", "No: inestabilidad afectiva y miedo al abandono", "Sí: daña a otros sin culpa ni cambio", "No: desconfianza sistemática, sin esa conducta", "No: desapego y frialdad sin intención de dañar"],
      {0: "Obsesivo", 1: "Limítrofe", 2: "Antisocial", 3: "Paranoide", 4: "Esquizoide"}),
  d=dict(rotulo="Criterios del trastorno antisocial (DSM-5-TR): tres o más", tag="CLAVE DEL CASO",
         pasos=[("Edad de 18 años o más, con trastorno de conducta antes de los 15", "Requisito de inicio: el patrón se remonta a la infancia o adolescencia", False),
                ("Incumplimiento de las normas legales, engaño y manipulación", "Mentiras repetidas y uso de los demás para su beneficio", False),
                ("Impulsividad, irritabilidad y agresiones", "Desprecio imprudente por la seguridad propia o ajena", False),
                ("Irresponsabilidad sostenida", "Fallas repetidas en el trabajo y en las obligaciones", False),
                ("Ausencia de remordimiento", "No siente culpa ni cambia a pesar de las consecuencias: el dato del caso", True)],
         no_hacer=[("Buscar un fármaco específico", "No existe; la psicoterapia rinde poco"), ("Confundir con esquizoide", "Ese es frío y desapegado, sin intención de dañar"), ("Olvidar el consumo de sustancias", "Es la comorbilidad que se busca y se trata")],
         veredicto=("Satisfacción propia a costa de otros + sin culpa = antisocial", "Obsesivo, limítrofe, paranoide y esquizoide tienen otros patrones.")))

